import os,json,subprocess,hashlib
from pathlib import Path
P=Path
def m(s):
 p=P(s)
 if p.is_symlink():return {'kind':'symlink','target':str(p.resolve(strict=False))}
 if not p.exists():return {'kind':'absent'}
 t=p.stat()
 return {'kind':'directory' if p.is_dir() else 'file','uid':t.st_uid,'gid':t.st_gid,'mode':oct(t.st_mode&0o7777),'size':t.st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() and t.st_size<200000 else None}
paths=['/etc/fadego-staging/app.env','/etc/fadego-staging/send-closed.env','/root/project-secrets/fadego-gmail/oauth.env','/root/project-secrets/fadego-staging/admin-password','/srv/projects/fadego/private','/srv/projects/fadego/private/systemd-env','/srv/projects/fadego/tools','/usr/local/sbin/fadego-password','/etc/pink-iptv','/etc/pink-iptv/backend.env','/etc/pink-iptv/secrets.env','/etc/pink-iptv/vpn.env','/srv/projects/pink-iptv/backend/private','/srv/projects/pink-iptv/private','/srv/projects/pink-iptv/backend','/srv/pink-iptv','/srv/projects/lowcost-europa/private/systemd-env','/etc/lowcost-europa']
d={'paths':{p:m(p) for p in paths},'user_services':{},'consumers':[],'root_secrets_metadata':[],'paths_in_process':[],'process_commands':{}}
for b in ['/root/project-secrets','/etc/pink-iptv','/etc/fadego-staging']:
 p=P(b)
 if p.is_dir():
  d['root_secrets_metadata']+=[{'path':str(q),'kind':m(q)['kind'],'mode':m(q).get('mode'),'size':m(q).get('size')} for q in p.iterdir()]
for service in ['fadego-staging','pink-iptv-backend','pink-vpn','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads']:
 a=subprocess.run(['systemctl','cat',service],capture_output=True,text=True,timeout=12)
 d['user_services'][service]=[l.strip()[:300] for l in a.stdout.splitlines() if l.strip().startswith(('WorkingDirectory=','ExecStart=','EnvironmentFile=','ReadWritePaths=','User=','Group=','ExecStartPre='))][:25]
need=['/srv/pink-iptv','/etc/pink-iptv/','/etc/fadego-staging/','/root/project-secrets/','/etc/lowcost-europa','/usr/local/sbin/fadego-password']
for root in ['/etc/systemd/system','/etc/nginx','/etc/cron.d','/usr/local/bin','/usr/local/sbin']:
 base=P(root)
 if not base.is_dir():continue
 for cur,dirs,files in os.walk(base):
  depth=len(P(cur).relative_to(base).parts)
  if depth>3:dirs[:]=[];continue
  for fname in files:
   f=P(cur)/fname
   try:
    if not f.is_file() or f.stat().st_size>500000:continue
    txt=f.read_text(errors='replace')
    matches=[q for q in need if q in txt]
    if matches:d['consumers'].append({'file':str(f),'references':matches})
   except Exception:pass
for proc in P('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  cwd=os.readlink(proc/'cwd');exe=os.readlink(proc/'exe')
  comm=(proc/'comm').read_text().strip()
  hits=[x for x in need if cwd.startswith(x) or exe.startswith(x)]
  if hits:d['paths_in_process'].append({'comm':comm,'paths':hits})
  if comm in ('uvicorn','node','python3') and len(d['process_commands'])<8:
   # Only show executable/cwd, not command line arguments that may carry secrets.
   d['process_commands'][proc.name]={'comm':comm,'cwd':cwd,'exe':exe}
 except Exception:pass
print(json.dumps(d,separators=(',',':'),ensure_ascii=True))
